const body = $json.body || $json;
const action = String(body.action || '').trim();
const cursoId = body.curso_id;
const institucionId = body.institucion_id;
if (!cursoId || !institucionId) throw new Error('curso_id e institucion_id son obligatorios.');
if (!['delete_document', 'clear_course'].includes(action)) throw new Error('action debe ser delete_document o clear_course.');
const archivo = action === 'delete_document' ? String(body.archivo || '').trim() : null;
if (action === 'delete_document' && !archivo) throw new Error('archivo es obligatorio para delete_document.');
return [{ json: { action, archivo, namespace: `inst_${institucionId}_curso_${cursoId}` } }];
